import type { ClaimStatus, PersonCandidate } from "@surveybeat/domain";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

const CandidateRow = Schema.Struct({
  organization_id: OrganizationId,
  name: Schema.String,
  person_id: PersonId,
  linked: Schema.Finite,
});

const ClaimRow = Schema.Struct({
  organization_id: OrganizationId,
  name: Schema.String,
  admin_person_id: PersonId,
  completed_at: Schema.NullOr(Schema.Finite),
});

const decodeRows = <S extends Schema.Top & { readonly DecodingServices: never }>(schema: S) =>
  Schema.decodeUnknownEffect(Schema.Array(schema));

const toCandidate = (row: typeof CandidateRow.Type): PersonCandidate => ({
  organization: { id: row.organization_id, name: row.name },
  personId: row.person_id,
  linked: row.linked === 1,
});

const toClaim = (row: typeof ClaimRow.Type): ClaimStatus => ({
  organization: { id: row.organization_id, name: row.name },
  adminPersonId: row.admin_person_id,
  completed: row.completed_at !== null,
});

export const d1PeopleIndex = (db: Cloudflare.D1.QueryDatabaseClient) =>
  Effect.gen(function* () {
    const runtime = yield* Effect.context<RuntimeContext>();

    const run = <A, E>(effect: Effect.Effect<A, E, RuntimeContext>): Effect.Effect<A> =>
      effect.pipe(Effect.provideContext(runtime), Effect.orDie);

    const all = (sql: string, ...binds: readonly unknown[]) =>
      db
        .prepare(sql)
        .bind(...binds)
        .all()
        .pipe(Effect.map((result) => result.results));

    const write = (sql: string, ...binds: readonly unknown[]) =>
      run(
        db
          .prepare(sql)
          .bind(...binds)
          .run(),
      ).pipe(Effect.asVoid);

    const claimOf = (userId: string) =>
      run(
        all(
          `SELECT organization_id, name, admin_person_id, completed_at
             FROM organization_claim WHERE auth_user_id = ?`,
          userId,
        ).pipe(Effect.flatMap(decodeRows(ClaimRow))),
      ).pipe(Effect.map((rows) => Option.map(Option.fromNullishOr(rows[0]), toClaim)));

    return PeopleIndex.of({
      linkedPersons: (userId) =>
        run(
          all(
            `SELECT p.organization_id, o.name, p.person_id, 1 AS linked
               FROM person_index p JOIN organization_index o ON o.organization_id = p.organization_id
              WHERE p.auth_user_id = ?
              ORDER BY p.organization_id`,
            userId,
          ).pipe(Effect.flatMap(decodeRows(CandidateRow))),
        ).pipe(Effect.map((rows) => rows.map(toCandidate))),

      unlinkedPersons: (email) =>
        run(
          all(
            `SELECT p.organization_id, o.name, p.person_id, 0 AS linked
               FROM person_index p JOIN organization_index o ON o.organization_id = p.organization_id
              WHERE p.email = ? AND p.auth_user_id IS NULL
              ORDER BY p.organization_id`,
            normaliseEmail(email),
          ).pipe(Effect.flatMap(decodeRows(CandidateRow))),
        ).pipe(Effect.map((rows) => rows.map(toCandidate))),

      putOrganization: (organization) =>
        write(
          `INSERT INTO organization_index (organization_id, name) VALUES (?, ?)
           ON CONFLICT (organization_id) DO UPDATE SET name = excluded.name`,
          organization.id,
          organization.name,
        ),

      putPerson: (person) =>
        write(
          `INSERT INTO person_index (organization_id, person_id, email, auth_user_id) VALUES (?, ?, ?, ?)
           ON CONFLICT (organization_id, person_id) DO UPDATE SET
             auth_user_id = coalesce(auth_user_id, excluded.auth_user_id)`,
          person.organizationId,
          person.personId,
          EmailAddress.make(normaliseEmail(person.email)),
          Option.getOrNull(person.userId),
        ),

      removePerson: (organizationId, personId) =>
        write(
          "DELETE FROM person_index WHERE organization_id = ? AND person_id = ?",
          organizationId,
          personId,
        ),

      linkPerson: (organizationId, personId, userId) =>
        write(
          `UPDATE person_index SET auth_user_id = ?
            WHERE organization_id = ? AND person_id = ? AND auth_user_id IS NULL`,
          userId,
          organizationId,
          personId,
        ),

      claimOrganization: (userId, proposed) =>
        write(
          `INSERT INTO organization_claim (auth_user_id, organization_id, name, admin_person_id)
           VALUES (?, ?, ?, ?) ON CONFLICT (auth_user_id) DO NOTHING`,
          userId,
          proposed.organization.id,
          proposed.organization.name,
          proposed.adminPersonId,
        ).pipe(
          Effect.andThen(claimOf(userId)),
          Effect.flatMap(
            Option.match({
              onNone: () => Effect.die("organization_claim row vanished after insert"),
              onSome: Effect.succeed,
            }),
          ),
        ),

      claimOf,

      completeClaim: (userId, now) =>
        write(
          "UPDATE organization_claim SET completed_at = ? WHERE auth_user_id = ? AND completed_at IS NULL",
          now,
          userId,
        ),
    });
  });

-- The global index for sign-in (SPEC §6.2, ADR 0002): what must be looked up before the
-- Organization is known. Persons themselves live in their Organization's Durable Object; these
-- rows only route to them. Emails are stored normalised (trimmed, lower case). No survey content.

-- Organization → its WorkOS organization (one to one), and the name the picker shows.
CREATE TABLE organization_index (
  organization_id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  workos_organization_id TEXT UNIQUE
) WITHOUT ROWID;

-- One row per Person. `workos_user_id` is NULL until the Person first signs in and is linked by
-- an exact match on a verified email; after that the row is found by user, not by email.
CREATE TABLE person_index (
  organization_id TEXT NOT NULL,
  person_id TEXT NOT NULL,
  email TEXT NOT NULL CHECK (email = lower(trim(email))),
  workos_user_id TEXT,
  PRIMARY KEY (organization_id, person_id)
) WITHOUT ROWID;

-- WorkOS user → Persons.
CREATE INDEX person_index_by_user ON person_index (workos_user_id) WHERE workos_user_id IS NOT NULL;
-- email → Organizations, for Persons not yet linked.
CREATE INDEX person_index_unlinked_by_email ON person_index (email) WHERE workos_user_id IS NULL;
-- A WorkOS user is at most one Person per Organization.
CREATE UNIQUE INDEX person_index_one_per_organization
  ON person_index (organization_id, workos_user_id) WHERE workos_user_id IS NOT NULL;

-- "Create an Organization" is idempotent per WorkOS user: the first claim wins, and every retry
-- or double submit finishes that same Organization.
CREATE TABLE organization_claim (
  workos_user_id TEXT NOT NULL PRIMARY KEY,
  organization_id TEXT NOT NULL UNIQUE,
  name TEXT NOT NULL,
  admin_person_id TEXT NOT NULL
) WITHOUT ROWID;

-- The deny list: WorkOS sessions (`sid`) signed out or revoked. Checked on every request, because
-- an access token stays valid until it expires. Keyed by session, not Organization, since one
-- session moves between Organizations when it is refreshed into another one.
CREATE TABLE revoked_session (
  session_id TEXT NOT NULL PRIMARY KEY,
  revoked_at INTEGER NOT NULL
) WITHOUT ROWID;
-- A claim closes once its Organization is finished, so a creator removed later is never made
-- admin again by finishing it (ADR 0002). NULL while the creation may still be finished.
ALTER TABLE organization_claim ADD COLUMN completed_at INTEGER;

-- Claims made before this column: finished once the creator's Person was linked in the index.
UPDATE organization_claim SET completed_at = unixepoch() * 1000
 WHERE EXISTS (
   SELECT 1 FROM person_index p
    WHERE p.organization_id = organization_claim.organization_id
      AND p.workos_user_id = organization_claim.workos_user_id
 );
-- Better Auth's own tables (ADR 0022): who signed in, and the session each cookie names. They sit
-- beside the people index rather than inside it, so the `auth_` prefix keeps them apart from
-- `person_index`, `organization_index` and `revoked_session`. Columns and indexes are Better Auth
-- 1.7.11's SQLite schema for packages/auth's model names; the Organization object still holds the
-- Persons, so no survey content is here.

CREATE TABLE auth_user (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  email TEXT NOT NULL UNIQUE,
  emailVerified INTEGER NOT NULL,
  image TEXT,
  createdAt DATE NOT NULL,
  updatedAt DATE NOT NULL
);

CREATE TABLE auth_session (
  id TEXT NOT NULL PRIMARY KEY,
  expiresAt DATE NOT NULL,
  token TEXT NOT NULL UNIQUE,
  createdAt DATE NOT NULL,
  updatedAt DATE NOT NULL,
  ipAddress TEXT,
  userAgent TEXT,
  userId TEXT NOT NULL REFERENCES auth_user (id) ON DELETE CASCADE
);

CREATE TABLE auth_account (
  id TEXT NOT NULL PRIMARY KEY,
  accountId TEXT NOT NULL,
  providerId TEXT NOT NULL,
  userId TEXT NOT NULL REFERENCES auth_user (id) ON DELETE CASCADE,
  accessToken TEXT,
  refreshToken TEXT,
  idToken TEXT,
  accessTokenExpiresAt DATE,
  refreshTokenExpiresAt DATE,
  scope TEXT,
  password TEXT,
  createdAt DATE NOT NULL,
  updatedAt DATE NOT NULL
);

CREATE TABLE auth_verification (
  id TEXT NOT NULL PRIMARY KEY,
  identifier TEXT NOT NULL,
  value TEXT NOT NULL,
  expiresAt DATE NOT NULL,
  createdAt DATE NOT NULL,
  updatedAt DATE NOT NULL
);

CREATE INDEX auth_session_userId_idx ON auth_session (userId);
CREATE INDEX auth_account_userId_idx ON auth_account (userId);
CREATE INDEX auth_verification_identifier_idx ON auth_verification (identifier);
ALTER TABLE auth_user ADD COLUMN role TEXT;
ALTER TABLE auth_user ADD COLUMN banned INTEGER DEFAULT 0;
ALTER TABLE auth_user ADD COLUMN banReason TEXT;
ALTER TABLE auth_user ADD COLUMN banExpires DATE;

ALTER TABLE auth_session ADD COLUMN impersonatedBy TEXT;
ALTER TABLE auth_session ADD COLUMN activeOrganizationId TEXT;

CREATE TABLE auth_organization (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  logo TEXT,
  createdAt DATE NOT NULL,
  metadata TEXT
);

CREATE TABLE auth_member (
  id TEXT NOT NULL PRIMARY KEY,
  organizationId TEXT NOT NULL REFERENCES auth_organization (id) ON DELETE CASCADE,
  userId TEXT NOT NULL REFERENCES auth_user (id) ON DELETE CASCADE,
  role TEXT NOT NULL DEFAULT 'member',
  createdAt DATE NOT NULL
);

CREATE TABLE auth_invitation (
  id TEXT NOT NULL PRIMARY KEY,
  organizationId TEXT NOT NULL REFERENCES auth_organization (id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  role TEXT,
  status TEXT NOT NULL DEFAULT 'pending',
  expiresAt DATE NOT NULL,
  createdAt DATE NOT NULL,
  inviterId TEXT NOT NULL REFERENCES auth_user (id) ON DELETE CASCADE
);

CREATE TABLE auth_passkey (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT,
  publicKey TEXT NOT NULL,
  userId TEXT NOT NULL REFERENCES auth_user (id) ON DELETE CASCADE,
  credentialID TEXT NOT NULL,
  counter INTEGER NOT NULL,
  deviceType TEXT NOT NULL,
  backedUp INTEGER NOT NULL,
  transports TEXT,
  createdAt DATE,
  aaguid TEXT
);

CREATE INDEX auth_organization_slug_idx ON auth_organization (slug);
CREATE INDEX auth_member_organizationId_idx ON auth_member (organizationId);
CREATE INDEX auth_member_userId_idx ON auth_member (userId);
CREATE INDEX auth_invitation_organizationId_idx ON auth_invitation (organizationId);
CREATE INDEX auth_invitation_email_idx ON auth_invitation (email);
CREATE INDEX auth_passkey_userId_idx ON auth_passkey (userId);
CREATE INDEX auth_passkey_credentialID_idx ON auth_passkey (credentialID);
ALTER TABLE person_index RENAME COLUMN workos_user_id TO auth_user_id;

ALTER TABLE organization_claim RENAME COLUMN workos_user_id TO auth_user_id;

CREATE TABLE organization_index_next (
  organization_id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL
) WITHOUT ROWID;

INSERT INTO organization_index_next (organization_id, name)
SELECT organization_id, name FROM organization_index;

DROP TABLE organization_index;

ALTER TABLE organization_index_next RENAME TO organization_index;

DROP TABLE IF EXISTS revoked_session;

CREATE TABLE IF NOT EXISTS auth_session_organization (
  session_id TEXT NOT NULL PRIMARY KEY REFERENCES auth_session (id) ON DELETE CASCADE,
  organization_id TEXT NOT NULL
) WITHOUT ROWID;

-- The Organization's People (ADR 0002, 0006). A Person exists before signing in (email only) and
-- is linked to an auth user at first sign-in by an exact match on a verified email. The per-request
-- session check asks this table whether the signed-in user's Person is still active.
-- Org-level roles (admin, member) are the Organization's own (SPEC §5.6, ADR 0003), so none is stored here.
CREATE TABLE person (
  id TEXT NOT NULL PRIMARY KEY,
  email TEXT NOT NULL CHECK (email = lower(trim(email))),
  auth_user_id TEXT UNIQUE,
  removed_at INTEGER
) WITHOUT ROWID;
-- Teams, Memberships, Organization admins, and the minimum group size (slice 04, ADR 0002–0004).

-- The Durable Object, not a token claim, decides who is an Organization admin (ADR 0010); the
-- `organization_admin` flag is kept in step. Until now the only Person was each Organization's creator,
-- made its admin, so every existing Person is one.
ALTER TABLE person ADD COLUMN organization_admin INTEGER NOT NULL DEFAULT 0 CHECK (organization_admin IN (0, 1));
UPDATE person SET organization_admin = 1;
-- One Person per email: adding an email that has a Person reuses (or restores) it.
CREATE UNIQUE INDEX person_email ON person (email);

-- N, at least 3 (ADR 0004). Each Round will store the N it closed under.
ALTER TABLE organization ADD COLUMN minimum_group_size INTEGER NOT NULL DEFAULT 4 CHECK (minimum_group_size >= 3);

-- Teams do not nest in Release 1: no parent. `time_zone` is an IANA name, checked by the domain.
CREATE TABLE team (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL,
  time_zone TEXT NOT NULL
) WITHOUT ROWID;
CREATE UNIQUE INDEX team_name ON team (lower(name));

-- A Person's role in one Team over a date range. Ending a Membership sets `ended_at`; rows are
-- never deleted, so history stays. A role change ends one Membership and starts another.
CREATE TABLE membership (
  id TEXT NOT NULL PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES team (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  role TEXT NOT NULL CHECK (role IN ('lead', 'member', 'viewer')),
  started_at INTEGER NOT NULL,
  ended_at INTEGER CHECK (ended_at IS NULL OR ended_at >= started_at)
) WITHOUT ROWID;
-- At most one active Membership per Person and Team.
CREATE UNIQUE INDEX membership_active ON membership (team_id, person_id) WHERE ended_at IS NULL;
CREATE INDEX membership_by_person ON membership (person_id);
-- One row per transactional send (ADR 0006). `state` is the domain's SendState as JSON;
-- `status` repeats its tag so a Lead's view can list failed sends without decoding every row.
CREATE TABLE email_send (
  id TEXT NOT NULL PRIMARY KEY,
  recipient TEXT NOT NULL,
  content TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('Pending', 'Sending', 'Sent', 'Failed')),
  state TEXT NOT NULL
) WITHOUT ROWID;
-- Invitations, reminders, and failed-send view (slice 08, ADR 0005, ADR 0006, ADR 0007).

-- Exactly-once sending enforced on the Invitation row (pending -> sending -> sent | failed(reason)).
CREATE TABLE invitation (
  round_id TEXT NOT NULL REFERENCES round (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  token_hash TEXT NOT NULL UNIQUE,
  send_id TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'sending', 'sent', 'failed', 'revoked')),
  failed_reason TEXT,
  resend_count INTEGER NOT NULL DEFAULT 0,
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  PRIMARY KEY (round_id, person_id)
) WITHOUT ROWID;

CREATE INDEX invitation_by_token ON invitation (token_hash);
CREATE INDEX invitation_by_status ON invitation (round_id, status);

-- Reminder opt-out per Person per Pulse (RFC 8058).
CREATE TABLE pulse_reminder_opt_out (
  pulse_id TEXT NOT NULL REFERENCES pulse (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  opted_out_at INTEGER NOT NULL,
  PRIMARY KEY (pulse_id, person_id)
) WITHOUT ROWID;

-- Person's preferred time zone (defaults to Team's time zone if null).
ALTER TABLE person ADD COLUMN time_zone TEXT;

-- Participation record: created when member answers (held apart from answers, ADR 0005).
-- Used by reminder jobs to skip members who have already answered.
CREATE TABLE IF NOT EXISTS participation (
  round_id TEXT NOT NULL REFERENCES round (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  PRIMARY KEY (round_id, person_id)
) WITHOUT ROWID;
-- Actions committed from a Result (slice 13).
CREATE TABLE action (
  id TEXT NOT NULL PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES team (id) ON DELETE CASCADE,
  round_id TEXT NOT NULL REFERENCES round (id) ON DELETE CASCADE,
  title TEXT NOT NULL,
  owner_id TEXT NOT NULL REFERENCES person (id),
  due_date TEXT,
  dimension TEXT,
  status TEXT NOT NULL CHECK (status IN ('proposed', 'committed', 'done', 'dropped')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL,
  done_at INTEGER
) WITHOUT ROWID;

CREATE INDEX action_by_team ON action (team_id);
CREATE INDEX action_by_round ON action (round_id);
-- Test sends (ADR 0021, issue 136): one row per "send me a test" email, kept for the rate limit (a
-- Person may send at most 5 an hour) and for indexing the test token once the email is sent. Rows
-- older than the test token's 7-day lifetime are deleted. Nothing here is about answers: a test never
-- writes a Submission, an Answer, or a Participation record.
CREATE TABLE test_send (
  send_id TEXT NOT NULL PRIMARY KEY,
  person_id TEXT NOT NULL,
  pulse_id TEXT NOT NULL,
  token_hash TEXT NOT NULL,
  sent_at INTEGER NOT NULL
) WITHOUT ROWID;

CREATE INDEX test_send_by_person ON test_send (person_id, sent_at);
-- Languages (ADR 0018). A Person's own choice (NULL: follow the browser), the browser language last
-- seen at sign-in (for emails, which have no browser), and the Organization's default.
ALTER TABLE person ADD COLUMN locale TEXT CHECK (locale IN ('en', 'de'));
ALTER TABLE person ADD COLUMN detected_locale TEXT CHECK (detected_locale IN ('en', 'de'));
ALTER TABLE organization ADD COLUMN default_locale TEXT NOT NULL DEFAULT 'en' CHECK (default_locale IN ('en', 'de'));

-- The question library and Pulses (slice 06). Question content and Pulse settings are checked by
-- the domain's schemas; the checks here keep the Release 1 limits from drifting in storage.

-- A Question in the Organization's library. `template_key` names the Template Question it was
-- copied from, if any.
CREATE TABLE question (
  id TEXT NOT NULL PRIMARY KEY,
  template_key TEXT,
  created_at INTEGER NOT NULL
) WITHOUT ROWID;

-- One meaning of a Question. Answers will point here, never at the Question. `type` is the
-- Question type as JSON (rating, single choice, long text; an open union).
CREATE TABLE question_version (
  id TEXT NOT NULL PRIMARY KEY,
  question_id TEXT NOT NULL REFERENCES question (id),
  number INTEGER NOT NULL CHECK (number >= 1),
  text TEXT NOT NULL,
  dimension TEXT CHECK (dimension IN ('workload', 'psychologicalSafety', 'clarity', 'recognition')),
  type TEXT NOT NULL CHECK (json_valid(type))
) WITHOUT ROWID;
-- Release 1 keeps exactly one version per Question. Drop this index when Questions get new versions.
CREATE UNIQUE INDEX question_version_one_per_question ON question_version (question_id);

-- A recurring check-in for one Team. Release 1: weekly only, 06:00–21:00 local, anonymous only,
-- by Invitation only.
CREATE TABLE pulse (
  id TEXT NOT NULL PRIMARY KEY,
  team_id TEXT NOT NULL REFERENCES team (id),
  name TEXT NOT NULL,
  cadence TEXT NOT NULL CHECK (cadence IN ('weekly')),
  weekday TEXT NOT NULL
    CHECK (weekday IN ('monday', 'tuesday', 'wednesday', 'thursday', 'friday', 'saturday', 'sunday')),
  send_time TEXT NOT NULL CHECK (send_time BETWEEN '06:00' AND '21:00' AND length(send_time) = 5),
  answer_window_days INTEGER NOT NULL CHECK (answer_window_days BETWEEN 1 AND 6),
  reminders INTEGER NOT NULL CHECK (reminders BETWEEN 0 AND 2),
  anonymity_mode TEXT NOT NULL CHECK (anonymity_mode IN ('anonymous')),
  distribution TEXT NOT NULL CHECK (distribution IN ('invitation')),
  created_at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE INDEX pulse_by_team ON pulse (team_id);

-- A Pulse's Question versions, in order. Each at most once per Pulse.
CREATE TABLE pulse_question (
  pulse_id TEXT NOT NULL REFERENCES pulse (id),
  position INTEGER NOT NULL CHECK (position >= 0),
  question_version_id TEXT NOT NULL REFERENCES question_version (id),
  PRIMARY KEY (pulse_id, position)
) WITHOUT ROWID;
CREATE UNIQUE INDEX pulse_question_once ON pulse_question (pulse_id, question_version_id);
-- Round lifecycle engine and schedule table (slice 07, ADR 0004, ADR 0006).

-- A Pulse can be paused by its Lead; cancelling its Scheduled Round until resumed.
ALTER TABLE pulse ADD COLUMN paused_at INTEGER;

-- Skipped cadence weeks for a Pulse (up to 8 weeks out).
CREATE TABLE pulse_skip (
  pulse_id TEXT NOT NULL REFERENCES pulse (id),
  planned_open_date TEXT NOT NULL,
  created_at INTEGER NOT NULL,
  PRIMARY KEY (pulse_id, planned_open_date)
) WITHOUT ROWID;

-- One Round of a Pulse: Scheduled -> Open -> Closed -> Ready -> Shared, or Cancelled.
-- Keyed by (pulse_id, planned_open_date) so duplicate rounds are impossible.
CREATE TABLE round (
  id TEXT NOT NULL PRIMARY KEY,
  pulse_id TEXT NOT NULL REFERENCES pulse (id),
  team_id TEXT NOT NULL REFERENCES team (id),
  status TEXT NOT NULL CHECK (status IN ('scheduled', 'open', 'closed', 'ready', 'shared', 'cancelled')),
  planned_open_date TEXT NOT NULL,
  planned_open_at INTEGER NOT NULL,
  opened_at INTEGER,
  planned_close_at INTEGER NOT NULL,
  closed_at INTEGER,
  effective_minimum_group_size INTEGER,
  pulse_name TEXT NOT NULL,
  answer_window_days INTEGER NOT NULL CHECK (answer_window_days BETWEEN 1 AND 6),
  reminders INTEGER NOT NULL CHECK (reminders BETWEEN 0 AND 2),
  anonymity_mode TEXT NOT NULL CHECK (anonymity_mode IN ('anonymous')),
  distribution TEXT NOT NULL CHECK (distribution IN ('invitation')),
  created_at INTEGER NOT NULL,
  updated_at INTEGER NOT NULL
) WITHOUT ROWID;

CREATE UNIQUE INDEX round_pulse_planned_date ON round (pulse_id, planned_open_date);
CREATE INDEX round_by_pulse ON round (pulse_id);
CREATE INDEX round_by_team ON round (team_id);
CREATE INDEX round_by_status ON round (status);

-- Questions frozen at the moment the Round opens.
CREATE TABLE round_question (
  round_id TEXT NOT NULL REFERENCES round (id),
  position INTEGER NOT NULL CHECK (position >= 0),
  question_version_id TEXT NOT NULL REFERENCES question_version (id),
  PRIMARY KEY (round_id, position)
) WITHOUT ROWID;
CREATE UNIQUE INDEX round_question_once ON round_question (round_id, question_version_id);

-- Eligible members frozen from active Memberships at the moment the Round opens.
CREATE TABLE round_member (
  round_id TEXT NOT NULL REFERENCES round (id),
  person_id TEXT NOT NULL REFERENCES person (id),
  time_zone TEXT NOT NULL,
  send_at INTEGER NOT NULL,
  PRIMARY KEY (round_id, person_id)
) WITHOUT ROWID;
CREATE INDEX round_member_by_person ON round_member (person_id);

-- Due jobs for the DO alarm (ADR 0006): open, close, compute, send, remind.
CREATE TABLE schedule_job (
  id TEXT NOT NULL PRIMARY KEY,
  round_id TEXT NOT NULL REFERENCES round (id),
  type TEXT NOT NULL CHECK (type IN ('open', 'close', 'compute', 'send', 'remind')),
  due_at INTEGER NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending', 'running', 'completed', 'cancelled')),
  payload TEXT,
  created_at INTEGER NOT NULL,
  completed_at INTEGER
) WITHOUT ROWID;

CREATE INDEX schedule_job_due ON schedule_job (status, due_at);
CREATE INDEX schedule_job_round ON schedule_job (round_id);
-- Sends this Organization created or requeued that are not yet on the Email queue (transactional outbox).
-- A row is written in the same transaction as its email_send; the alarm puts the rows on the queue and
-- deletes exactly the rows it sent. A repeated message is harmless: delivery claims each send once.
CREATE TABLE email_outbox (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  send_id TEXT NOT NULL
);
-- One-time repairs of stored data. `name` is the repair's stable key; a row means it has run for this Organization.
CREATE TABLE maintenance_done (
  name TEXT NOT NULL PRIMARY KEY,
  done_at INTEGER NOT NULL
) WITHOUT ROWID;
CREATE TABLE organization (
  id TEXT NOT NULL PRIMARY KEY,
  name TEXT NOT NULL
) WITHOUT ROWID;
