    },
  ],
  notIncluded: [
    "Submissions and Answers are not in this file. A stored Submission and Answer has no Person column (ADR 0005), so SurveyBeat cannot tell which ones are yours. A comment that still identifies its author can be personal data. Ask your Organization or write to the privacy contact to have it found.",
    "Team Results and the personal data of any other Person are not in this file.",
    "Secrets are not in this file: no session token, sign-in code, password, Invitation link or token, token hash, or passkey credential.",
  ],
  browserLocalData:
    "Answers kept in this browser, and the Edit keys of Submissions made from it, are stored only in your browser, never on SurveyBeat's servers. View or clear them on /history (ADR 0017).",
  yourRights: `You can ask for correction, erasure, restriction or objection by writing to ${Legal.privacyEmail}. SurveyBeat answers within ${Legal.responseDays} days. Requests about data held for an Organization are passed to that Organization.`,
};

export interface PersonalDataSourceShape {
  readonly gather: (userId: AuthUserId, now: number) => Effect.Effect<PersonalDataExport>;
}

export class PersonalDataSource extends Context.Service<PersonalDataSource, PersonalDataSourceShape>()(
  "@surveybeat/domain/PersonalDataSource",
) {}

export const assemblePersonalDataExport = (parts: {
  readonly now: number;
  readonly account: AccountData;
  readonly organizations: readonly OrganizationPersonalData[];
}): PersonalDataExport => ({
  schemaVersion: PERSONAL_DATA_EXPORT_SCHEMA_VERSION,
  exportedAt: new Date(parts.now).toISOString(),
  transparency: personalDataTransparency,
  account: parts.account,
  organizations: [...parts.organizations].sort((a, b) => a.organization.id.localeCompare(b.organization.id)),
});

export { AuthUserId };

import type { SqliteClient } from "@effect/sql-sqlite-do";
import { isoTimestamp, OrganizationId } from "@surveybeat/domain";
import type { OrganizationPersonalData } from "@surveybeat/domain";
import * as Effect from "effect/Effect";

interface PersonRow {
  readonly id: string;
  readonly email: string;
  readonly time_zone: string | null;
  readonly locale: string | null;
  readonly detected_locale: string | null;
  readonly organization_admin: number;
  readonly removed_at: number | null;
}

export const organizationPersonalData = (sql: SqliteClient.SqliteClient) => ({
  exportPersonalData: (authUserId: string): Effect.Effect<OrganizationPersonalData | null> =>
    Effect.gen(function* () {
      const people = yield* sql<PersonRow>`
        SELECT id, email, time_zone, locale, detected_locale, organization_admin, removed_at
          FROM person WHERE auth_user_id = ${authUserId}`;

      const person = people[0];

      if (person === undefined) {
        return null;
      }

      const organizations = yield* sql<{ id: string; name: string }>`
        SELECT id, name FROM organization LIMIT 1`;

      const memberships = yield* sql<{
        id: string;
        team_id: string;
        team_name: string;
        role: string;
        started_at: number;
        ended_at: number | null;
      }>`
        SELECT membership.id, membership.team_id, team.name AS team_name, membership.role,
               membership.started_at, membership.ended_at
          FROM membership JOIN team ON team.id = membership.team_id
         WHERE membership.person_id = ${person.id}
         ORDER BY membership.started_at, membership.id`;

      const participation = yield* sql<{ round_id: string; planned_open_date: string; pulse_name: string }>`
        SELECT round.id AS round_id, round.planned_open_date, round.pulse_name
          FROM participation JOIN round ON round.id = participation.round_id
         WHERE participation.person_id = ${person.id}
         ORDER BY round.planned_open_date, round.id`;

      const roundMembers = yield* sql<{
        round_id: string;
        planned_open_date: string;
        pulse_name: string;
        send_at: number;
        time_zone: string;
      }>`
        SELECT round.id AS round_id, round.planned_open_date, round.pulse_name,
               round_member.send_at, round_member.time_zone
          FROM round_member JOIN round ON round.id = round_member.round_id
         WHERE round_member.person_id = ${person.id}
         ORDER BY round.planned_open_date, round.id`;

      const invitations = yield* sql<{
        round_id: string;
        planned_open_date: string;
        pulse_name: string;
        status: string;
        resend_count: number;
        created_at: number;
        updated_at: number;
      }>`
        SELECT round.id AS round_id, round.planned_open_date, round.pulse_name,
               invitation.status, invitation.resend_count, invitation.created_at, invitation.updated_at
          FROM invitation JOIN round ON round.id = invitation.round_id
         WHERE invitation.person_id = ${person.id}
         ORDER BY round.planned_open_date, round.id`;

      const reminderOptOuts = yield* sql<{ pulse_id: string; pulse_name: string; opted_out_at: number }>`
        SELECT pulse.id AS pulse_id, pulse.name AS pulse_name, pulse_reminder_opt_out.opted_out_at
          FROM pulse_reminder_opt_out JOIN pulse ON pulse.id = pulse_reminder_opt_out.pulse_id
         WHERE pulse_reminder_opt_out.person_id = ${person.id}
         ORDER BY pulse.id`;

      const actions = yield* sql<{
        id: string;
        team_id: string;
        round_id: string;
        title: string;
        due_date: string | null;
        dimension: string | null;
        status: string;
        created_at: number;
        updated_at: number;
        done_at: number | null;
      }>`
        SELECT id, team_id, round_id, title, due_date, dimension, status, created_at, updated_at, done_at
          FROM action WHERE owner_id = ${person.id} ORDER BY created_at, id`;

      const emailSends = yield* sql<{
        id: string;
        kind: string | null;
        status: string;
        sent_at: number | null;
        failed_at: number | null;
      }>`
        SELECT id, json_extract(content, '$._tag') AS kind, status,
               json_extract(state, '$.sentAt') AS sent_at, json_extract(state, '$.failedAt') AS failed_at
          FROM email_send WHERE recipient = ${person.email} ORDER BY id`;

      const testSends = yield* sql<{
        send_id: string;
        pulse_id: string;
        pulse_name: string | null;
        sent_at: number;
      }>`
        SELECT test_send.send_id, test_send.pulse_id, pulse.name AS pulse_name, test_send.sent_at
          FROM test_send LEFT JOIN pulse ON pulse.id = test_send.pulse_id
         WHERE test_send.person_id = ${person.id} ORDER BY test_send.sent_at, test_send.send_id`;

      const organization = organizations[0];

      return {
        organization: {
          id: OrganizationId.make(organization?.id ?? ""),
          name: organization?.name ?? "",
        },
        person: {
          id: person.id,
          email: person.email,
          timeZone: person.time_zone,
          locale: person.locale,
          detectedLocale: person.detected_locale,
          organizationAdmin: person.organization_admin === 1,
          removedAt: isoTimestamp(person.removed_at),
        },
        memberships: memberships.map((row) => ({
          id: row.id,
          teamId: row.team_id,
          teamName: row.team_name,
          role: row.role,
          startedAt: isoTimestamp(row.started_at),
          endedAt: isoTimestamp(row.ended_at),
        })),
        participation: participation.map((row) => ({
          roundId: row.round_id,
          plannedOpenDate: row.planned_open_date,
          pulseName: row.pulse_name,
          participated: true as const,
        })),
        roundMembers: roundMembers.map((row) => ({
          roundId: row.round_id,
          plannedOpenDate: row.planned_open_date,
          pulseName: row.pulse_name,
          sendAt: isoTimestamp(row.send_at),
          timeZone: row.time_zone,
        })),
        invitations: invitations.map((row) => ({
          roundId: row.round_id,
          plannedOpenDate: row.planned_open_date,
          pulseName: row.pulse_name,
          status: row.status,
          resendCount: row.resend_count,
          createdAt: isoTimestamp(row.created_at),
          updatedAt: isoTimestamp(row.updated_at),
        })),
        reminderOptOuts: reminderOptOuts.map((row) => ({
          pulseId: row.pulse_id,
          pulseName: row.pulse_name,
          optedOutAt: isoTimestamp(row.opted_out_at),
        })),
        actions: actions.map((row) => ({
          id: row.id,
          teamId: row.team_id,
          roundId: row.round_id,
          title: row.title,
          dueDate: row.due_date,
          dimension: row.dimension,
          status: row.status,
          createdAt: isoTimestamp(row.created_at),
          updatedAt: isoTimestamp(row.updated_at),
          doneAt: isoTimestamp(row.done_at),
        })),
        emailSends: emailSends.map((row) => ({
          id: row.id,
          kind: row.kind ?? "unknown",
          status: row.status,
          sentAt: isoTimestamp(row.sent_at),
          failedAt: isoTimestamp(row.failed_at),
        })),
        testSends: testSends.map((row) => ({
          id: row.send_id,
          pulseId: row.pulse_id,
          pulseName: row.pulse_name,
          sentAt: isoTimestamp(row.sent_at),
        })),
      } satisfies OrganizationPersonalData;
    }).pipe(Effect.orDie),
});

import type * as Cloudflare from "@alchemy.run/cloudflare";
import {
  assemblePersonalDataExport,
  isoTimestamp,
  OrganizationId,
  PersonalDataSource,
} from "@surveybeat/domain";
import type { AccountData, AuthUserId, OrganizationPersonalData } from "@surveybeat/domain";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as Effect from "effect/Effect";

type Cell = string | number | null;

type Row = Readonly<Record<string, Cell>>;

const text = (cell: Cell | undefined): string => (cell === null || cell === undefined ? "" : String(cell));

const nullableText = (cell: Cell | undefined): string | null =>
  cell === null || cell === undefined ? null : String(cell);

const stamp = (cell: Cell | undefined): string | null => isoTimestamp(cell);

const expiresAfter = (cell: Cell | undefined, now: number): boolean => {
  const iso = isoTimestamp(cell);

  return iso !== null && new Date(iso).getTime() > now;
};

export const readAccountData = (db: Cloudflare.D1.QueryDatabaseClient) => {
  const all = (sql: string, userId: string) =>
    db
      .prepare(sql)
      .bind(userId)
      .all<Row>()
      .pipe(Effect.map((result) => result.results));

  return (userId: AuthUserId, now: number): Effect.Effect<AccountData, never, RuntimeContext> =>
    Effect.gen(function* () {
      const users = yield* all(
        "SELECT id, name, email, emailVerified, createdAt, updatedAt FROM auth_user WHERE id = ?",
        userId,
      );

      const sessions = yield* all(
        `SELECT id, expiresAt, createdAt, updatedAt, ipAddress, userAgent
           FROM auth_session WHERE userId = ? ORDER BY createdAt, id`,
        userId,
      );

      const links = yield* all(
        `SELECT id, providerId, accountId, createdAt, updatedAt
           FROM auth_account WHERE userId = ? ORDER BY createdAt, id`,
        userId,
      );

      const passkeys = yield* all(
        "SELECT id, name, deviceType, createdAt FROM auth_passkey WHERE userId = ? ORDER BY createdAt, id",
        userId,
      );

      const index = yield* all(
        `SELECT p.organization_id, o.name, p.person_id, p.email
           FROM person_index p JOIN organization_index o ON o.organization_id = p.organization_id
          WHERE p.auth_user_id = ? ORDER BY p.organization_id`,
        userId,
      );

      const claims = yield* all(
        `SELECT organization_id, name, admin_person_id, completed_at
           FROM organization_claim WHERE auth_user_id = ? ORDER BY organization_id`,
        userId,
      );

      const user = users[0];

      return {
        user:
          user === undefined
            ? null
            : {
                id: text(user["id"]),
                name: text(user["name"]),
                email: text(user["email"]),
                emailVerified: user["emailVerified"] === 1 || user["emailVerified"] === "1",
                createdAt: stamp(user["createdAt"]),
                updatedAt: stamp(user["updatedAt"]),
              },
        activeSessions: sessions
          .filter((row) => expiresAfter(row["expiresAt"], now))
          .map((row) => ({
            id: text(row["id"]),
            createdAt: stamp(row["createdAt"]),
            updatedAt: stamp(row["updatedAt"]),
            expiresAt: stamp(row["expiresAt"]),
            ipAddress: nullableText(row["ipAddress"]),
            userAgent: nullableText(row["userAgent"]),
          })),
        providerLinks: links.map((row) => ({
          id: text(row["id"]),
          providerId: text(row["providerId"]),
          accountId: text(row["accountId"]),
          createdAt: stamp(row["createdAt"]),
          updatedAt: stamp(row["updatedAt"]),
        })),
        passkeys: passkeys.map((row) => ({
          id: text(row["id"]),
          name: nullableText(row["name"]),
          deviceType: text(row["deviceType"]),
          createdAt: stamp(row["createdAt"]),
        })),
        personIndex: index.map((row) => ({
          organizationId: OrganizationId.make(text(row["organization_id"])),
          organizationName: text(row["name"]),
          personId: text(row["person_id"]),
          email: text(row["email"]),
        })),
        organizationClaims: claims.map((row) => ({
          organizationId: OrganizationId.make(text(row["organization_id"])),
          name: text(row["name"]),
          adminPersonId: text(row["admin_person_id"]),
          completedAt: stamp(row["completed_at"]),
        })),
      } satisfies AccountData;
    }).pipe(Effect.orDie);
};

export interface PersonalDataOrganizations {
  readonly getByName: (id: string) => {
    readonly exportPersonalData: (authUserId: string) => Effect.Effect<OrganizationPersonalData | null>;
  };
}

export const personalDataSource = (
  db: Cloudflare.D1.QueryDatabaseClient,
  organizations: PersonalDataOrganizations,
) =>
  Effect.gen(function* () {
    const runtime = yield* Effect.context<RuntimeContext>();
    const account = readAccountData(db);

    return PersonalDataSource.of({
      gather: (userId, now) =>
        Effect.gen(function* () {
          const data = yield* account(userId, now).pipe(Effect.provideContext(runtime));

          const organizationIds = [
            ...new Set([
              ...data.personIndex.map((entry) => entry.organizationId),
              ...data.organizationClaims.map((claim) => claim.organizationId),
            ]),
          ].sort();

          const found = yield* Effect.forEach(
            organizationIds,
            (id) => organizations.getByName(id).exportPersonalData(userId),
            { concurrency: 4 },
          );

          return assemblePersonalDataExport({
            now,
            account: data,
            organizations: found.filter((each): each is OrganizationPersonalData => each !== null),
          });
        }),
    });
  });

