import { describe, expect, it } from "@effect/vitest";
import { Browser, SignInWorld } from "./testing.ts";

const setup = () => {
  const world = new SignInWorld();
  const acme = world.addOrganization("Acme");
  world.addPerson(acme.id, "admin@example.com", true);

  const as = async (email: string) => {
    const browser = new Browser(world.handler());
    browser.signIn(world.sessions.login(email));
    await browser.session();

    return browser;
  };

  return { world, as };
};

describe("personal data export endpoint (GDPR 306)", () => {
  it("refuses a caller who is not signed in", async () => {
    const { world } = setup();
    const response = await new Browser(world.handler()).get("/api/me/data-export");

    expect(response.status).toBe(401);
  });

  it("downloads a versioned JSON attachment for a signed-in Organization admin", async () => {
    const { as } = setup();
    const response = await (await as("admin@example.com")).get("/api/me/data-export");
    const body = (await response.json()) as {
      readonly schemaVersion: number;
      readonly account: { readonly user: { readonly email: string } };
      readonly organizations: readonly { readonly person: { readonly organizationAdmin: boolean } }[];
    };

    expect(response.status).toBe(200);
    expect(response.headers.get("content-disposition")).toBe(
      'attachment; filename="surveybeat-personal-data.json"',
    );
    expect(response.headers.get("cache-control")).toBe("no-store");
    expect(response.headers.get("content-type")).toContain("application/json");
    expect(body.schemaVersion).toBe(1);
    expect(body.account.user.email).toBe("admin@example.com");
    expect(body.organizations.map((each) => each.person.organizationAdmin)).toEqual([true]);
  });

  it("downloads for a signed-in human who belongs to no Organization", async () => {
    const { as } = setup();
    const response = await (await as("stranger@example.com")).get("/api/me/data-export");
    const body = (await response.json()) as {
      readonly account: { readonly user: { readonly email: string } };
      readonly organizations: readonly unknown[];
    };

    expect(response.status).toBe(200);
    expect(body.account.user.email).toBe("stranger@example.com");
    expect(body.organizations).toEqual([]);
  });

  it("refuses a request from another origin", async () => {
    const { as } = setup();

    const response = await (await as("admin@example.com")).fetch("/api/me/data-export", {
      headers: { origin: "https://evil.example" },
    });

    expect(response.status).toBe(403);
  });
});
